import React,{useEffect,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowDownToLine,ArrowRight,ArrowUpRight,BarChart3,BookOpen,Box,Check,CheckCircle2,ChevronRight,ClipboardList,Database,FileCheck2,FlaskConical,HeartPulse,History,Info,Layers,LoaderCircle,Menu,ShieldCheck,SlidersHorizontal,Sparkles,Upload,X,RotateCcw,LockKeyhole,AlertCircle,LogIn,LogOut,UserRound,Search,GitCompareArrows,GraduationCap} from 'lucide-react';
import {api,Card,Chart,count,Empty,errorText,Field,fmt,Lang,Loading,MetricsTable,Note,post,T,Values} from './ui';
